INSERT INTO AYE120 (/*SQL-ID : isry.couns.constt.etcntabrd.mapper.BbsVocListMapper : 고객의소리(답글추가)*/ FRST_RGTR_ID /*작성자아이디*/ , WRTR_NM_ENCPT /*작성자명*/ , RETE_CN /*답글내용*/ , BBSCTT_ESNTAL_NO /*게시글번호*/ , BBSCTT_TYPE_SE_CD /*게시글유형구분코드*/ , RETE_ESNTAL_NO /*답글고유번호*/ , RETE_TTL_NM /*답글제목*/
, ATFINO /*첨부파일명*/
) VALUES ( #{FRST_RGTR_ID} /*작성자아이디*/ , #{WRTR_NM_ENCPT} /*작성자명*/ , #{RETE_CN} /*답글내용*/ , #{BBSCTT_ESNTAL_NO} /*게시글번호*/ , '09' /*게시글유형구분코드*/ , #{BBSCTT_ESNTAL_NO} /* AYE120_SQ01.NEXTVAL 답글고유번호*/ , #{RETE_TTL_NM} /*답글제목*/
, #{ATFINO} /*첨부파일명*/
)

