UPDATE AYE120 SET /*SQL-ID : isry.couns.constt.etcntabrd.mapper.BbsVocListMapper :  고객의소리(답글수정)*/
            RETE_CN = #{RETE_CN}                  
            ,LAST_MDFCN_DT = SYSDATE 
            ,LAST_MDFR_ID = #{LAST_MDFR_ID}

            ,ATFINO = #{ATFINO}

WHERE       1=1
    AND     BBSCTT_TYPE_SE_CD = '09'
    AND     BBSCTT_ESNTAL_NO = #{BBSCTT_ESNTAL_NO__origin}
    AND     RETE_ESNTAL_NO = #{RETE_ESNTAL_NO__origin}

UPDATE AYE120 SET   /*SQL-ID : isry.couns.constt.etcntabrd.mapper.BbsVocListMapper :  고객의소리(답글삭제)*/
              DEL_YN = 'Y'
            , LAST_MDFCN_DT = SYSDATE     
            , LAST_MDFR_ID = #{LAST_MDFR_ID}
WHERE       1=1
    AND     BBSCTT_TYPE_SE_CD = '09'
    AND     BBSCTT_ESNTAL_NO = #{BBSCTT_ESNTAL_NO__origin}
    AND     RETE_ESNTAL_NO = #{RETE_ESNTAL_NO__origin}

UPDATE AYE110 SET /*SQL-ID : updateBbsRespodVoc1*/ CMNT_CN = #{CMNT_CN} ,LAST_MDFCN_DT = SYSDATE ,LAST_MDFR_ID = #{LAST_MDFR_ID} WHERE 1=1 AND BBSCTT_TYPE_SE_CD = '09'
AND BBSCTT_ESNTAL_NO = #{BBSCTT_ESNTAL_NO}
AND CMNT_ESNTAL_NO = #{CMNT_ESNTAL_NO}

UPDATE AYE110 SET   /*SQL-ID : deleteBbsRespodVoc1*/
              DEL_YN = 'Y'
            , LAST_MDFCN_DT = SYSDATE     
            , LAST_MDFR_ID = #{LAST_MDFR_ID}
WHERE       1=1
    AND     BBSCTT_TYPE_SE_CD = '09'

    AND     BBSCTT_ESNTAL_NO = #{BBSCTT_ESNTAL_NO      }

    AND     CMNT_ESNTAL_NO = #{CMNT_ESNTAL_NO}
